from datetime import date, timedelta
from collections import defaultdict


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # Track used leave days per employee per year: {employee: {year: used_days}}
        self._used: dict[str, dict[int, int]] = defaultdict(lambda: defaultdict(int))

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date.")

        if (start - today).days < 3:
            raise ValueError("Leave requests must be made at least 3 days before the start date.")

        # Calculate leave days requested per calendar year
        needed_by_year: dict[int, int] = defaultdict(int)
        curr = start
        while curr <= end:
            # Weekdays are 0-4 (Monday-Friday); weekends (5, 6) and holidays don't use leave days
            if curr.weekday() < 5 and curr not in self.holidays:
                needed_by_year[curr.year] += 1
            curr += timedelta(days=1)

        # Check if the employee has enough remaining days for each year in the request
        for year, needed in needed_by_year.items():
            if needed > self.remaining(employee, year):
                raise ValueError(
                    f"Employee '{employee}' does not have enough remaining leave days for year {year}."
                )

        # Deduct the days
        for year, needed in needed_by_year.items():
            self._used[employee][year] += needed

        return sum(needed_by_year.values())

    def remaining(self, employee: str, year: int) -> int:
        return self.days_per_year - self._used[employee][year]
```

